from typing import List

def terms(count: int) -> List[int]:
    x, out = 127, []
    for _ in range(count):
        out.append(x)
        x = 1000*x + 127
    return out

if __name__ == "__main__":
    for n, value in enumerate(terms(10)):
        print(n, value)

def compare(n: int) -> tuple[int, int, int]:
    x = 127
    for _ in range(n):
        x = 1000*x + 127
    closed = 127*(1000**(n+1)-1)//999
    block = int("127"*(n+1))
    assert x == closed == block
    return x, closed, block

if __name__ == "__main__":
    for n in range(12):
        print(n, compare(n))

def family_count(x: int) -> int:
    count, value = 0, 127
    while value <= x:
        count += 1
        value = 1000*value + 127
    return count

if __name__ == "__main__":
    for exponent in range(3, 31, 3):
        x = 10**exponent
        print(f"X=10^{exponent}: lower bound {family_count(x)}")

